<script setup lang="ts">
import { onMounted, onUnmounted, ref } from "vue";
import { ElMessage } from "element-plus";
import { consultationAdminApi as api } from "../../../api/consultation";
import type { ConsultationNotice, ConsultationPresence, ConsultationRequestV2 } from "../../../../../src/types/consultation";

defineOptions({ name: "ConsultantDashboard" });
const loading = ref(true); const error = ref("");
const requests = ref<ConsultationRequestV2[]>([]); const presence = ref<ConsultationPresence[]>([]); const notices = ref<ConsultationNotice[]>([]);
const metrics = ref([{ label: "待处理咨询", value: 0, note: "等待平台派单" }, { label: "已配对咨询", value: 0, note: "等待健管师接入" }, { label: "在线客户", value: 0, note: "当前心跳状态" }, { label: "未读通知", value: 0, note: "需要及时处理" }]);
const tasks = ref<ConsultationNotice[]>([]); let timer: ReturnType<typeof setInterval>;
async function load() { try { const [queue, requestQueue, notificationList] = await Promise.all([api.queue(), api.requestQueue(), api.notices()]); requests.value = requestQueue.requests; presence.value = queue.presence; notices.value = notificationList; metrics.value = [{ label: "待处理咨询", value: requestQueue.requests.filter(item => ["queued", "reassigned"].includes(item.status)).length, note: "等待平台派单" }, { label: "已配对咨询", value: requestQueue.requests.filter(item => ["assigned", "waiting_consultant", "in_progress"].includes(item.status)).length, note: "等待健管师接入" }, { label: "在线客户", value: queue.presence.filter(item => item.online).length, note: "当前心跳状态" }, { label: "未读通知", value: notificationList.filter(item => !item.read).length, note: "需要及时处理" }]; tasks.value = notificationList.filter(item => !item.read).slice(0, 5); error.value = "" } catch (e) { error.value = (e as Error).message } finally { loading.value = false } }
async function markRead(item: ConsultationNotice) { try { await api.read(item.id); await load(); ElMessage.success("通知已读") } catch (e) { ElMessage.error((e as Error).message) } }
onMounted(async () => { try { await api.login(); await load(); timer = setInterval(load, 10000) } catch (e) { error.value = (e as Error).message; loading.value = false } }); onUnmounted(() => clearInterval(timer));
</script>
<template><div class="page" v-loading="loading"><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="head"><div><h2>咨询工作概览</h2><p>数据来自实时派单、在线状态与通知接口</p></div><el-button type="primary" @click="load">刷新数据</el-button></div><el-row :gutter="16" class="metrics"><el-col v-for="item in metrics" :key="item.label" :xs="24" :sm="12" :md="6"><el-card shadow="never"><span class="muted">{{ item.label }}</span><strong>{{ item.value }}</strong><span class="green">{{ item.note }}</span></el-card></el-col></el-row><el-row :gutter="16"><el-col :xs="24" :md="14"><el-card shadow="never"><template #header><b>咨询状态</b></template><el-empty v-if="!requests.length" description="暂无咨询请求"/><el-table v-else :data="requests.slice(0, 8)" size="small"><el-table-column prop="userName" label="客户"/><el-table-column prop="mode" label="方式"/><el-table-column prop="status" label="状态"/><el-table-column prop="consultantName" label="健管师"><template #default="{row}">{{ row.consultantName || '待分配' }}</template></el-table-column></el-table></el-card></el-col><el-col :xs="24" :md="10"><el-card shadow="never"><template #header><b>待处理通知</b></template><el-empty v-if="!tasks.length" description="暂无未读通知"/><el-timeline v-else><el-timeline-item v-for="task in tasks" :key="task.id" type="warning" :timestamp="new Date(task.createdAt).toLocaleString('zh-CN')"><span>{{ task.title }}</span><el-button link type="primary" @click="markRead(task)">已读</el-button></el-timeline-item></el-timeline></el-card></el-col></el-row><el-card shadow="never" class="presence"><template #header><b>客户在线状态</b></template><el-table :data="presence" size="small" empty-text="暂无在线状态"><el-table-column prop="name" label="客户"/><el-table-column label="状态"><template #default="{row}">{{ row.online ? (row.idle ? '在线但暂无动作' : '在线活跃') : '离线' }}</template></el-table-column><el-table-column prop="lastActionAt" label="最后动作"/></el-table></el-card></div></template>
<style scoped>.page{padding:4px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}h2{margin:0}.muted,p{color:var(--el-text-color-secondary)}p{margin:8px 0}.metrics{margin-bottom:16px}.metrics strong{display:block;font-size:28px;margin:12px 0}.green{color:#12a88f;font-size:13px}.presence{margin-top:16px}.el-timeline-item .el-button{margin-left:10px}</style>
